    /**
     * Rebuilds the blob from its ASCII transport form.
     *
     * The data is carried as printable ASCII rather than as \uXXXX escapes in
     * the literals themselves because Kotlin/JS turns a *lone* surrogate in a
     * string literal into "?", which would silently corrupt the surrogate cases
     * this corpus exists to check.
     */
    private fun decodeTransport(s: String): String {
        val sb = StringBuilder(s.length)
        var i = 0
        while (i < s.length) {
            val c = s[i]
            if (c != '\\') {
                sb.append(c)
                i++
                continue
            }
            if (s[i + 1] == '\\') {
                sb.append('\\')
                i += 2
            } else {
                sb.append(s.substring(i + 1, i + 5).toInt(16).toChar())
                i += 5
            }
        }
        return sb.toString()
    }

    private val blob: String by lazy {
        decodeTransport(listOf(C0, C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13, C14, C15, C16, C17, C18, C19, C20, C21, C22, C23, C24, C25, C26, C27, C28, C29, C30, C31, C32, C33, C34, C35, C36, C37, C38, C39, C40, C41, C42, C43, C44, C45, C46, C47, C48, C49, C50, C51, C52, C53, C54, C55).joinToString(""))
    }

    private val parsed: List<Case> by lazy { parse(blob) }

    internal fun all(): List<Case> = parsed

    /** Mirrors the encoder in tools/difftest/gen-fixture.mjs. */
    private fun parse(s: String): List<Case> {
        val out = ArrayList<Case>(CASE_COUNT)
        var i = 0

        fun readInt(terminator: Char): Int {
            val start = i
            while (s[i] != terminator) i++
            val v = s.substring(start, i).toInt()
            i++ // consume terminator
            return v
        }

        fun readString(): String? {
            if (s[i] == 'N') {
                i++
                return null
            }
            val len = readInt(':')
            val v = s.substring(i, i + len)
            i += len
            return v
        }

        while (i < s.length) {
            val index = readInt(',')
            val groupCount = readInt(',')
            val pattern = readString()!!
            val flags = readString()!!
            val input = readString()
            val groups = ArrayList<String?>(groupCount)
            repeat(groupCount) { groups.add(readString()) }
            out.add(Case(pattern, flags, input, index, groups))
        }
        check(out.size == CASE_COUNT) { "fixture decoded ${out.size} cases, expected $CASE_COUNT" }
        return out
    }
